package com.memesforsale.oreratios;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Marks bank sprites of the selected recipe's inputs with the number still
 * needed for one trip, live-counting down against the current inventory.
 */
public class BankOverlay extends WidgetItemOverlay
{
	private static final Color REMAINING = Color.CYAN;
	private static final Color DONE = Color.GREEN;

	private final Client client;
	private final ItemManager itemManager;
	private final OreRatiosConfig config;
	private final BankOverlaySettings settings;

	@Inject
	BankOverlay(Client client, ItemManager itemManager, OreRatiosConfig config, BankOverlaySettings settings)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		this.settings = settings;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.bankOverlay())
		{
			return;
		}

		final int canonical = itemManager.canonicalize(itemId);
		final OreData recipe = settings.getRecipe();
		final boolean bf = settings.isBlastFurnace();
		final int bagCoal = settings.bagCoal();
		final int bars = recipe.barsPerTrip(bf, bagCoal);

		int needed = -1;
		for (final OreData.OreInput input : recipe.getInputs())
		{
			if (input.getItemId() == canonical)
			{
				needed = input.getCount() * bars;
				break;
			}
		}
		final int coalPerBar = recipe.coalPerBar(bf);
		if (canonical == ItemID.COAL && coalPerBar > 0)
		{
			needed = Math.max(0, coalPerBar * bars - bagCoal);
		}
		if (needed < 0)
		{
			return;
		}

		final ItemContainer inv = client.getItemContainer(InventoryID.INV);
		final int have = inv == null ? 0 : inv.count(canonical);
		final int toWithdraw = Math.max(0, needed - have);
		final Color color = toWithdraw == 0 ? DONE : REMAINING;
		final Rectangle bounds = widgetItem.getCanvasBounds();

		if (settings.isBorders())
		{
			graphics.setColor(color);
			// Grown outward so the border clears the withdraw number at the sprite's edge.
			graphics.drawRect(bounds.x - 2, bounds.y - 2, bounds.width + 4, bounds.height + 4);
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());
		final TextComponent text = new TextComponent();
		text.setPosition(new Point(bounds.x, bounds.y + bounds.height));
		text.setText(Integer.toString(toWithdraw));
		text.setColor(color);
		text.render(graphics);
	}
}

package com.memesforsale.oreratios;

import javax.inject.Singleton;

/**
 * The bank overlay's selected recipe and option overrides, configured from
 * the side panel. Overrides the plugin config for the bank overlay only.
 * Written on the Swing thread, read on the client thread by the overlay,
 * hence volatile fields.
 */
@Singleton
public class BankOverlaySettings
{
	private volatile OreData recipe = OreData.STEEL;
	private volatile boolean blastFurnace;
	private volatile OreRatiosConfig.CoalBagMode coalBagMode = OreRatiosConfig.CoalBagMode.NONE;
	private volatile boolean borders = true;

	public OreData getRecipe()
	{
		return recipe;
	}

	public void setRecipe(OreData recipe)
	{
		this.recipe = recipe;
	}

	public boolean isBlastFurnace()
	{
		return blastFurnace;
	}

	public void setBlastFurnace(boolean blastFurnace)
	{
		this.blastFurnace = blastFurnace;
	}

	public OreRatiosConfig.CoalBagMode getCoalBagMode()
	{
		return coalBagMode;
	}

	public void setCoalBagMode(OreRatiosConfig.CoalBagMode coalBagMode)
	{
		this.coalBagMode = coalBagMode;
	}

	public boolean isBorders()
	{
		return borders;
	}

	public void setBorders(boolean borders)
	{
		this.borders = borders;
	}

	public int bagCoal()
	{
		return coalBagMode.getCapacity();
	}
}

package com.memesforsale.oreratios;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * Furnace smelting recipes, keyed for lookup by any ore they consume.
 *
 * Slots per bar = sum(ore counts) + coal per bar.
 * Bars per trip = floor(28 / slotsPerBar).
 */
public enum OreData
{
	// Enum order = display order when an ore maps to multiple recipes (e.g. iron, copper).
	BRONZE("Bronze", "Bronze", 0,
		new OreInput("tin", ItemID.TIN_ORE, 1),
		new OreInput("copper", ItemID.COPPER_ORE, 1)),

	BLURITE("Blurite", "Blurite", 0,
		new OreInput("blurite", ItemID.BLURITE_ORE, 1)),

	IRON("Iron", "Iron", 0,
		new OreInput("iron", ItemID.IRON_ORE, 1)),

	SILVER("Silver", "Silver", 0,
		new OreInput("silver", ItemID.SILVER_ORE, 1)),

	LEAD("Lead", "Lead", 0,
		new OreInput("lead", ItemID.LEAD_ORE, 2)),

	STEEL("Steel", "Steel", 2,
		new OreInput("iron", ItemID.IRON_ORE, 1)),

	GOLD("Gold", "Gold", 0,
		new OreInput("gold", ItemID.GOLD_ORE, 1)),

	LOVAKITE("Lovakite", "Lovak", 2,
		new OreInput("lovakite", ItemID.LOVAKITE_ORE, 1)),

	MITHRIL("Mithril", "Mith", 4,
		new OreInput("mithril", ItemID.MITHRIL_ORE, 1)),

	CUPRONICKEL("Cupronickel", "Cupro", 0,
		new OreInput("copper", ItemID.COPPER_ORE, 2),
		new OreInput("nickel", ItemID.NICKEL_ORE, 1)),

	ADAMANTITE("Adamantite", "Addy", 6,
		new OreInput("adamantite", ItemID.ADAMANTITE_ORE, 1)),

	RUNITE("Runite", "Rune", 8,
		new OreInput("runite", ItemID.RUNITE_ORE, 1));

	public static final int INVENTORY_SIZE = 28;
	public static final int COAL_BAG_CAPACITY = 27;
	public static final int COAL_BAG_SMITHING_CAPE_CAPACITY = 36;

	private final String barName;
	private final String abbrev;
	private final int baseCoalPerBar;
	private final OreInput[] inputs;

	private static final Map<Integer, List<OreData>> BY_ORE_ID;
	private static final List<OreData> COAL_RECIPES;

	static
	{
		final Map<Integer, List<OreData>> byOre = new HashMap<>();
		final List<OreData> coalRecipes = new ArrayList<>();

		for (final OreData recipe : values())
		{
			for (final OreInput input : recipe.inputs)
			{
				byOre.computeIfAbsent(input.itemId, k -> new ArrayList<>()).add(recipe);
			}
			if (recipe.baseCoalPerBar > 0)
			{
				coalRecipes.add(recipe);
			}
		}

		byOre.replaceAll((k, v) -> Collections.unmodifiableList(v));
		BY_ORE_ID = Collections.unmodifiableMap(byOre);
		COAL_RECIPES = Collections.unmodifiableList(coalRecipes);
	}

	OreData(String barName, String abbrev, int baseCoalPerBar, OreInput... inputs)
	{
		this.barName = barName;
		this.abbrev = abbrev;
		this.baseCoalPerBar = baseCoalPerBar;
		this.inputs = inputs;
	}

	/** All recipes consuming the given ore item id (empty list if not an ore tracked). */
	public static List<OreData> recipesFor(int itemId)
	{
		return BY_ORE_ID.getOrDefault(itemId, Collections.emptyList());
	}

	/** Recipes that consume coal, in enum order, used for the Coal hover summary. */
	public static List<OreData> coalRecipes()
	{
		return COAL_RECIPES;
	}

	public String getBarName()
	{
		return barName;
	}

	public String getAbbrev()
	{
		return abbrev;
	}

	public int getBaseCoalPerBar()
	{
		return baseCoalPerBar;
	}

	public List<OreInput> getInputs()
	{
		return Collections.unmodifiableList(Arrays.asList(inputs));
	}

	/** Coal per bar; Blast Furnace halves coal usage, rounded up. */
	public int coalPerBar(boolean blastFurnace)
	{
		return blastFurnace ? (baseCoalPerBar + 1) / 2 : baseCoalPerBar;
	}

	public int orePerBar()
	{
		int total = 0;
		for (final OreInput input : inputs)
		{
			total += input.count;
		}
		return total;
	}

	public int slotsPerBar(boolean blastFurnace)
	{
		return orePerBar() + coalPerBar(blastFurnace);
	}

	/**
	 * Max bars per 28-slot trip. A coal bag (bagCoal > 0) takes one slot and supplies
	 * up to bagCoal coal before inventory coal is needed; it is ignored for recipes
	 * that use no coal.
	 */
	public int barsPerTrip(boolean blastFurnace, int bagCoal)
	{
		final int coal = coalPerBar(blastFurnace);
		if (bagCoal <= 0 || coal == 0)
		{
			return INVENTORY_SIZE / slotsPerBar(blastFurnace);
		}

		final int slots = INVENTORY_SIZE - 1;
		int bars = slots / orePerBar();
		while (bars > 0 && bars * orePerBar() + Math.max(0, bars * coal - bagCoal) > slots)
		{
			bars--;
		}
		return bars;
	}

	/** e.g. "1 iron + 2 coal", "2 copper + 1 nickel", "2 lead", "1 silver". */
	public String recipeString(boolean blastFurnace)
	{
		final StringBuilder sb = new StringBuilder();
		for (final OreInput input : inputs)
		{
			if (sb.length() > 0)
			{
				sb.append(" + ");
			}
			sb.append(input.count).append(' ').append(input.shortName);
		}
		final int coal = coalPerBar(blastFurnace);
		if (coal > 0)
		{
			sb.append(" + ").append(coal).append(" coal");
		}
		return sb.toString();
	}

	/** e.g. "9 iron + 18 coal = 9 bars (27/28)", "18 iron + 9 coal + coal bag = 18 bars (28/28)". */
	public String tripString(boolean blastFurnace, int bagCoal)
	{
		final int coal = coalPerBar(blastFurnace);
		final boolean useBag = bagCoal > 0 && coal > 0;
		final int bars = barsPerTrip(blastFurnace, useBag ? bagCoal : 0);
		final StringBuilder sb = new StringBuilder();
		for (final OreInput input : inputs)
		{
			if (sb.length() > 0)
			{
				sb.append(" + ");
			}
			sb.append(input.count * bars).append(' ').append(input.shortName);
		}
		final int invCoal = useBag ? Math.max(0, coal * bars - bagCoal) : coal * bars;
		if (invCoal > 0)
		{
			sb.append(" + ").append(invCoal).append(" coal");
		}
		if (useBag)
		{
			sb.append(" + coal bag");
		}
		sb.append(" = ").append(bars).append(bars == 1 ? " bar" : " bars");
		final int slotsUsed = orePerBar() * bars + invCoal + (useBag ? 1 : 0);
		sb.append(" (").append(slotsUsed).append('/').append(INVENTORY_SIZE).append(')');
		return sb.toString();
	}

	/**
	 * Max bars smeltable from current bank stock, limited by whichever input runs out
	 * first (each ore input, plus coal for coal recipes). {@code bankCount} maps an
	 * item id to its banked quantity.
	 */
	public int bankBars(boolean blastFurnace, java.util.function.IntUnaryOperator bankCount)
	{
		int bars = Integer.MAX_VALUE;
		for (final OreInput input : inputs)
		{
			bars = Math.min(bars, bankCount.applyAsInt(input.itemId) / input.count);
		}
		final int coal = coalPerBar(blastFurnace);
		if (coal > 0)
		{
			bars = Math.min(bars, bankCount.applyAsInt(ItemID.COAL) / coal);
		}
		return bars == Integer.MAX_VALUE ? 0 : bars;
	}

	/** Coal required to smelt every banked ore of this recipe (ignores banked coal). */
	public int coalForAllOre(boolean blastFurnace, java.util.function.IntUnaryOperator bankCount)
	{
		int bars = Integer.MAX_VALUE;
		for (final OreInput input : inputs)
		{
			bars = Math.min(bars, bankCount.applyAsInt(input.itemId) / input.count);
		}
		return bars == Integer.MAX_VALUE ? 0 : bars * coalPerBar(blastFurnace);
	}

	/** Inputs the bank lacks for even one bar, e.g. "tin" or "nickel, coal". */
	public String missingInputs(boolean blastFurnace, java.util.function.IntUnaryOperator bankCount)
	{
		final StringBuilder sb = new StringBuilder();
		for (final OreInput input : inputs)
		{
			if (bankCount.applyAsInt(input.itemId) < input.count)
			{
				if (sb.length() > 0)
				{
					sb.append(", ");
				}
				sb.append(input.shortName);
			}
		}
		final int coal = coalPerBar(blastFurnace);
		if (coal > 0 && bankCount.applyAsInt(ItemID.COAL) < coal)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append("coal");
		}
		return sb.toString();
	}

	/** True if the bank holds at least one of any ore this recipe consumes. */
	public boolean hasInputStock(java.util.function.IntUnaryOperator bankCount)
	{
		for (final OreInput input : inputs)
		{
			if (bankCount.applyAsInt(input.itemId) > 0)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Leftover stock after smelting {@code bars} bars, e.g. "6 iron, 32 coal left".
	 * Empty string when nothing is left over.
	 */
	public String bankLeftover(boolean blastFurnace, int bars, java.util.function.IntUnaryOperator bankCount)
	{
		final StringBuilder sb = new StringBuilder();
		for (final OreInput input : inputs)
		{
			final int left = bankCount.applyAsInt(input.itemId) - bars * input.count;
			if (left > 0)
			{
				if (sb.length() > 0)
				{
					sb.append(", ");
				}
				sb.append(left).append(' ').append(input.shortName);
			}
		}
		final int coal = coalPerBar(blastFurnace);
		if (coal > 0)
		{
			final int leftCoal = bankCount.applyAsInt(ItemID.COAL) - bars * coal;
			if (leftCoal > 0)
			{
				if (sb.length() > 0)
				{
					sb.append(", ");
				}
				sb.append(leftCoal).append(" coal");
			}
		}
		return sb.toString();
	}

	static final class OreInput
	{
		private final String shortName;
		private final int itemId;
		private final int count;

		OreInput(String shortName, int itemId, int count)
		{
			this.shortName = shortName;
			this.itemId = itemId;
			this.count = count;
		}

		public String getShortName()
		{
			return shortName;
		}

		public int getItemId()
		{
			return itemId;
		}

		public int getCount()
		{
			return count;
		}
	}
}

package com.memesforsale.oreratios;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("oreratios")
public interface OreRatiosConfig extends Config
{
	@ConfigItem(
		keyName = "showInBank",
		name = "Show in bank",
		description = "Show tooltips when hovering items inside the bank item container. "
			+ "The inventory-side panel while banking is always treated as inventory.",
		position = 1
	)
	default boolean showInBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBarsPerTrip",
		name = "Show bars per trip",
		description = "Show the optimal 28-slot inventory split and bars-per-trip line.",
		position = 2
	)
	default boolean showBarsPerTrip()
	{
		return true;
	}

	@ConfigItem(
		keyName = "blastFurnaceMode",
		name = "Blast Furnace mode",
		description = "Halve coal per bar (rounded up) and calculate trip splits accordingly.",
		position = 3
	)
	default boolean blastFurnaceMode()
	{
		return false;
	}

	@ConfigItem(
		keyName = "coalBagMode",
		name = "Coal bag",
		description = "Assume a full coal bag (takes 1 inventory slot) when calculating trip splits. "
			+ "Holds 27 coal, or 36 with the Smithing cape perk.",
		position = 4
	)
	default CoalBagMode coalBagMode()
	{
		return CoalBagMode.NONE;
	}

	enum CoalBagMode
	{
		NONE("None", 0),
		COAL_BAG("Bag only (27)", OreData.COAL_BAG_CAPACITY),
		COAL_BAG_SMITHING_CAPE("+ Cape (36)", OreData.COAL_BAG_SMITHING_CAPE_CAPACITY);

		private final String label;
		private final int capacity;

		CoalBagMode(String label, int capacity)
		{
			this.label = label;
			this.capacity = capacity;
		}

		public int getCapacity()
		{
			return capacity;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "showBankTotals",
		name = "Show bank totals",
		description = "Using your banked ore and coal counts, show how many bars you can smelt and what would be left over. ",
		position = 6
	)
	default boolean showBankTotals()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankOverlay",
		name = "Bank overlay",
		description = "Show the bank overlay options sidebar. While enabled, bank sprites of the selected "
			+ "recipe's ores are marked with how many you still need to withdraw for one trip.",
		position = 7
	)
	default boolean bankOverlay()
	{
		return false;
	}
}

package com.memesforsale.oreratios;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

/**
 * Follows the core Item Prices plugin (ItemPricesOverlay) hover-detection pattern:
 * read the last client menu entry in render(), confirm it targets an inventory/bank
 * item widget, extract the item id, and push a Tooltip via TooltipManager.
 */
public class OreRatiosOverlay extends Overlay
{
	private static final Color HEADER = new Color(255, 152, 31);   // recipe name
	private static final Color TEXT = Color.WHITE;                 // ratios
	private static final Color MUTED = new Color(170, 170, 170);   // trip line / notes

	private final Client client;
	private final OreRatiosConfig config;
	private final TooltipManager tooltipManager;
	private final ItemManager itemManager;

	@Inject
	OreRatiosOverlay(Client client, OreRatiosConfig config, TooltipManager tooltipManager, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.tooltipManager = tooltipManager;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// No tooltip while the right-click menu is open.
		if (client.isMenuOpen())
		{
			return null;
		}

		final MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
		final int last = menuEntries.length - 1;
		if (last < 0)
		{
			return null;
		}

		final MenuEntry menuEntry = menuEntries[last];
		final MenuAction action = menuEntry.getType();
		final int widgetId = menuEntry.getParam1();
		final int groupId = WidgetUtil.componentToInterface(widgetId);

		switch (action)
		{
			case WIDGET_TARGET:
			case CC_OP:
			case CC_OP_LOW_PRIORITY:
				if (groupId == InterfaceID.INVENTORY || groupId == InterfaceID.BANKSIDE)
				{
					addTooltip(menuEntry);
				}
				else if (groupId == InterfaceID.BANKMAIN && config.showInBank())
				{
					addTooltip(menuEntry);
				}
				break;
			default:
				break;
		}

		return null;
	}

	private void addTooltip(MenuEntry menuEntry)
	{
		int itemId = menuEntry.getItemId();
		if (itemId <= 0)
		{
			final Widget widget = menuEntry.getWidget();
			if (widget != null)
			{
				itemId = widget.getItemId();
			}
		}
		if (itemId <= 0)
		{
			return;
		}

		// Map noted items and bank placeholders back to the base item.
		itemId = itemManager.canonicalize(itemId);

		final String text = itemId == ItemID.COAL
			? buildCoalTooltip()
			: buildOreTooltip(itemId);

		if (text != null)
		{
			tooltipManager.add(new Tooltip(text));
		}
	}

	private String buildOreTooltip(int itemId)
	{
		final List<OreData> recipes = OreData.recipesFor(itemId);
		if (recipes.isEmpty())
		{
			return null;
		}

		final boolean bf = config.blastFurnaceMode();
		final int bagCoal = bagCoal();
		final IntUnaryOperator bank = bankCounter();
		final StringBuilder sb = new StringBuilder();

		for (final OreData recipe : recipes)
		{
			if (sb.length() > 0)
			{
				sb.append("</br>");
			}

			final boolean bfApplies = bf && recipe.getBaseCoalPerBar() > 0;
			sb.append(ColorUtil.wrapWithColorTag(
				recipe.getBarName() + " bar" + (bfApplies ? " (BF)" : "") + ": ", HEADER));
			sb.append(ColorUtil.wrapWithColorTag(recipe.recipeString(bf), TEXT));

			if (recipe == OreData.IRON && !bf)
			{
				sb.append(ColorUtil.wrapWithColorTag(" (50% w/o Ring of forging)", MUTED));
			}

			if (config.showBarsPerTrip())
			{
				sb.append("</br>");
				sb.append(ColorUtil.wrapWithColorTag("Trip: " + recipe.tripString(bf, bagCoal), MUTED));
			}

			if (bank != null && recipe.hasInputStock(bank))
			{
				sb.append("</br>");
				sb.append(ColorUtil.wrapWithColorTag(
					"Bank: " + bankSummary(recipe, bf, bagCoal, bank), TEXT));
			}
		}

		return sb.toString();
	}

	private String buildCoalTooltip()
	{
		final boolean bf = config.blastFurnaceMode();
		final StringBuilder sb = new StringBuilder();

		sb.append(ColorUtil.wrapWithColorTag(bf ? "BF coal per bar: " : "Coal per bar: ", HEADER));

		final StringBuilder ratios = new StringBuilder();
		for (final OreData recipe : OreData.coalRecipes())
		{
			if (ratios.length() > 0)
			{
				ratios.append(" | ");
			}
			ratios.append(recipe.getAbbrev()).append(" 1:").append(recipe.coalPerBar(bf));
		}
		sb.append(ColorUtil.wrapWithColorTag(ratios.toString(), TEXT));

		final IntUnaryOperator bank = bankCounter();
		if (bank != null)
		{
			final int bagCoal = bagCoal();

			int coalNeeded = 0;
			for (final OreData recipe : OreData.coalRecipes())
			{
				coalNeeded += recipe.coalForAllOre(bf, bank);
			}
			if (coalNeeded > 0)
			{
				final int diff = bank.applyAsInt(ItemID.COAL) - coalNeeded;
				sb.append("</br>");
				sb.append(ColorUtil.wrapWithColorTag("Coal needed for all ore: ", HEADER));
				sb.append(ColorUtil.wrapWithColorTag(Integer.toString(coalNeeded), TEXT));
				if (diff != 0)
				{
					sb.append(ColorUtil.wrapWithColorTag(
						diff > 0 ? " (" + diff + " spare)" : " (" + -diff + " short)", MUTED));
				}
			}

			boolean headerAdded = false;
			for (final OreData recipe : OreData.coalRecipes())
			{
				if (!recipe.hasInputStock(bank))
				{
					continue;
				}

				if (!headerAdded)
				{
					sb.append("</br>");
					sb.append(ColorUtil.wrapWithColorTag("Bank (all coal to one type):", HEADER));
					headerAdded = true;
				}

				sb.append("</br>");
				sb.append(ColorUtil.wrapWithColorTag(recipe.getAbbrev() + ": ", MUTED));
				sb.append(ColorUtil.wrapWithColorTag(bankSummary(recipe, bf, bagCoal, bank), TEXT));
			}
		}

		return sb.toString();
	}

	/** e.g. "5 trips | 84 bars (6 iron, 32 coal left)" or "0 bars (short on coal)". */
	private String bankSummary(OreData recipe, boolean bf, int bagCoal, IntUnaryOperator bank)
	{
		final int bars = recipe.bankBars(bf, bank);
		if (bars == 0)
		{
			return "0 bars (need " + recipe.missingInputs(bf, bank) + ")";
		}

		final int perTrip = recipe.barsPerTrip(bf, bagCoal);
		final int trips = (bars + perTrip - 1) / perTrip;
		final String leftover = recipe.bankLeftover(bf, bars, bank);
		return trips + (trips == 1 ? " trip" : " trips")
			+ " | " + bars + (bars == 1 ? " bar" : " bars")
			+ (leftover.isEmpty() ? "" : " (" + leftover + " left)");
	}

	private int bagCoal()
	{
		return config.coalBagMode().getCapacity();
	}

	private IntUnaryOperator bankCounter()
	{
		if (!config.showBankTotals())
		{
			return null;
		}
		final ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		return bank == null ? null : bank::count;
	}
}

package com.memesforsale.oreratios;

import java.awt.Component;
import java.awt.Font;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Bank overlay options. Settings here override the plugin config for the
 * bank withdraw overlay only; hover tooltips keep following the plugin config.
 */
public class OreRatiosPanel extends PluginPanel
{
	private final BankOverlaySettings settings;

	private final JComboBox<OreData> recipeBox = new JComboBox<>(OreData.values());
	private final JCheckBox blastFurnaceBox = new JCheckBox("Blast Furnace");
	private final JComboBox<OreRatiosConfig.CoalBagMode> coalBagBox =
		new JComboBox<>(OreRatiosConfig.CoalBagMode.values());
	private final JCheckBox bordersBox = new JCheckBox("Borders");
	private final JLabel summary = new JLabel();

	@Inject
	OreRatiosPanel(BankOverlaySettings settings, OreRatiosConfig config)
	{
		this.settings = settings;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		// Seed the coal bag from the global config; Blast Furnace always starts off.
		coalBagBox.setSelectedItem(config.coalBagMode());
		recipeBox.setSelectedItem(settings.getRecipe());
		bordersBox.setSelected(settings.isBorders());

		recipeBox.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean isSelected, boolean cellHasFocus)
			{
				super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
				setText(((OreData) value).getBarName() + " bar");
				return this;
			}
		});

		final JLabel title = new JLabel("Bank overlay options");
		title.setFont(title.getFont().deriveFont(Font.BOLD));

		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		recipeBox.addActionListener(e -> update());
		blastFurnaceBox.addActionListener(e -> update());
		coalBagBox.addActionListener(e -> update());
		bordersBox.addActionListener(e -> update());

		addRow(title);
		addRow(new JLabel("Smelting"));
		addRow(recipeBox);
		addRow(blastFurnaceBox);
		addRow(new JLabel("Coal bag"));
		addRow(coalBagBox);
		addRow(bordersBox);
		addRow(summary);

		update();
	}

	private void addRow(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(c);
		add(Box.createVerticalStrut(8));
	}

	private void update()
	{
		final OreData recipe = (OreData) recipeBox.getSelectedItem();
		final boolean bf = blastFurnaceBox.isSelected();
		final OreRatiosConfig.CoalBagMode bag =
			(OreRatiosConfig.CoalBagMode) coalBagBox.getSelectedItem();

		settings.setRecipe(recipe);
		settings.setBlastFurnace(bf);
		settings.setCoalBagMode(bag);
		settings.setBorders(bordersBox.isSelected());

		summary.setText("<html>Trip: " + recipe.tripString(bf, bag.getCapacity()) + "</html>");
	}
}

package com.memesforsale.oreratios;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Ore Ratios",
	description = "Hover ores in inventory/bank to see coal per bar and the optimal 28-slot trip split",
	tags = {"smithing", "coal", "ore", "blast", "furnace", "tooltip", "bars"}
)
public class OreRatiosPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OreRatiosOverlay overlay;

	@Inject
	private BankOverlay bankOverlay;

	@Inject
	private OreRatiosConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(bankOverlay);
		updateNavButton();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(bankOverlay);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("oreratios".equals(event.getGroup()))
		{
			updateNavButton();
		}
	}

	private void updateNavButton()
	{
		if (config.bankOverlay() && navButton == null)
		{
			navButton = NavigationButton.builder()
				.tooltip("Ore Ratios")
				.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
				.priority(7)
				.panel(injector.getInstance(OreRatiosPanel.class))
				.build();
			clientToolbar.addNavigation(navButton);
		}
		else if (!config.bankOverlay() && navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
	}

	@Provides
	OreRatiosConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OreRatiosConfig.class);
	}
}

